-- Case de Macroeconomia: mc-simplificado (A decisão do Copom). Importado do protótipo "Elas na Ilha". Todos os dados são fictícios.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  $$mc-simplificado$$,
  $$A decisão do Copom$$,
  'macroeconomia',
  $$Atue como analista da Arquipélago Investimentos: leia o relatório macro da semana, preveja a decisão do Copom e recomende o que fazer com a carteira, em cinco capítulos curtos e uma defesa diante do comitê.$$,
  $$Prever a decisão do Copom e recomendar o que fazer com a carteira.$$,
  $$Você é analista da Arquipélago Investimentos (gestora fictícia). Marina, diretora do programa de analistas, é sua chefe nesta ilha. O Copom decide na quarta e o comitê (Helena, sócia; Ricardo, gestor; e Paula, de Risco e Operações) quer a sua leitura. Você vai fazer a análise em cinco capítulos curtos: o relatório, o diagnóstico do cenário, a projeção, uma reviravolta e a defesa no comitê. Você pode sair e voltar quando quiser: o progresso fica salvo. Todos os nomes, empresas e números são fictícios.$$,
  $${"resumo": "Macroeconomia é olhar a economia do país inteiro: juros, inflação, emprego, dólar. Economistas em bancos, gestoras e consultorias leem esses dados e projetam o que deve acontecer, e os gestores usam essas projeções para decidir onde investir. Neste desafio, você prevê a decisão do Copom e recomenda o que fazer com a carteira. Passe pelos cards, assista ao vídeo e veja como se entra na área (cerca de 15 minutos).", "links": [{"titulo": "Inflação e Selic: como o Banco Central controla a inflação", "url": "https://www.nordinvestimentos.com.br/blog/videos/inflacao-e-selic-como-o-banco-central-controla-a-inflacao/", "fonte": "Marilia Fontes, economista · Nord Investimentos"}, {"titulo": "BC te Explica: como surgiu o Copom", "url": "https://www.youtube.com/watch?v=b1a0Zmf_hbQ", "fonte": "Banco Central do Brasil (fonte oficial)"}], "cards": [{"titulo": "O que faz quem trabalha com macro", "texto": "Macroeconomia é olhar a economia do país inteiro: juros, inflação, emprego, dólar. Economistas em bancos, gestoras e consultorias leem esses dados e projetam o que deve acontecer. Os gestores usam essas projeções para decidir onde investir.", "naPratica": "Se a economista prevê juros subindo, a gestora pode ajustar a carteira antes."}, {"titulo": "Selic", "texto": "A taxa básica de juros do Brasil. Ela influencia quase todos os outros juros: do financiamento do carro ao rendimento da sua renda fixa (investimentos com regra de rendimento definida na compra, como Tesouro Direto e CDB).", "naPratica": "Selic alta deixa o crédito caro e a renda fixa mais atraente."}, {"titulo": "Inflação e meta", "texto": "Inflação é o aumento geral dos preços, medido no Brasil pelo IPCA (o índice oficial de inflação, calculado pelo IBGE). O governo define uma meta, com margem de tolerância, e o Banco Central (a instituição que cuida da moeda e da inflação do país) tem a missão de manter a inflação dentro dela.", "naPratica": "Quando a inflação passa do teto da meta, o Banco Central tende a agir."}, {"titulo": "Copom", "texto": "O comitê do Banco Central que decide a Selic. Ele se reúne periodicamente e pode subir, manter ou cortar os juros, explicando a decisão num comunicado.", "naPratica": "O mercado inteiro para para ver a decisão e ler o comunicado."}, {"titulo": "Câmbio", "texto": "O preço do dólar em reais. Dólar alto encarece importados, combustíveis e insumos, o que pressiona a inflação.", "naPratica": "Um dólar disparando pode levar o Banco Central a manter os juros altos por mais tempo."}, {"titulo": "Expectativas", "texto": "Toda semana, o Banco Central publica o boletim Focus (pesquisa semanal com as projeções de economistas do mercado), com o que esses economistas esperam para inflação, juros, PIB (a soma de tudo o que o país produz num período) e dólar. As expectativas influenciam preços e salários hoje.", "naPratica": "Se todos esperam inflação alta, o Banco Central se preocupa antes de ela acontecer."}], "comoSeEntra": {"ondeSeTrabalha": "Departamentos econômicos de bancos, gestoras, consultorias econômicas e áreas de estratégia de empresas.", "formacoes": "Economia é a mais tradicional; Administração, Contábeis e Engenharia também levam até lá.", "vagas": "Estágio em pesquisa econômica, estratégia de investimentos e programas de estágio de bancos e gestoras.", "oQueAjuda": "Excel e estatística, ler o boletim Focus e as atas do Copom, escrever análises curtas e participar de liga acadêmica.", "quandoRecrutam": "Muitos programas abrem uma vez por ano. Acompanhe as páginas de carreira das empresas."}}$$::jsonb,
  'publicado',
  15
)
ON CONFLICT (id) DO NOTHING;

