($$mc-cp-3$$, $$mc-simplificado$$, 3, $$treino$$, $$Treino de Macro (sem nota)$$, $$Seis perguntas rápidas sobre Selic, inflação, câmbio, atividade, expectativas e juros. A resposta vem na hora, com explicação.$$, 20, $$["mc-task-treino"]$$::jsonb),
($$mc-cp-4$$, $$mc-simplificado$$, 4, $$situacao$$, $$Capítulo 1: Briefing$$, $$Escolha os três dados do relatório que mais importam para a decisão do Copom e diga por quê.$$, 20, $$["mc-task-briefing"]$$::jsonb),
($$mc-cp-5$$, $$mc-simplificado$$, 5, $$situacao$$, $$Capítulo 2: Diagnóstico$$, $$Classifique o cenário (inflação, expectativas, atividade e juros) e explique.$$, 30, $$["mc-task-diagnostico"]$$::jsonb),
($$mc-cp-6$$, $$mc-simplificado$$, 6, $$situacao$$, $$Capítulo 3: Projeção$$, $$Decida o que o Copom faz, com que confiança, com qual argumento e o que fazer com a carteira.$$, 30, $$["mc-task-projecao"]$$::jsonb),
($$mc-cp-7$$, $$mc-simplificado$$, 7, $$situacao$$, $$Capítulo 4: Reviravolta$$, $$Uma notícia muda o cenário. Mantenha ou mude a projeção e explique.$$, 30, $$["mc-task-reviravolta"]$$::jsonb),
($$mc-cp-8$$, $$mc-simplificado$$, 8, $$defesa$$, $$Capítulo 5: o Comitê$$, $$Defenda sua projeção diante de Helena, Ricardo e Paula.$$, 40, $$["mc-task-comite"]$$::jsonb)
