INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
($$mc-task-treino$$, $$mc-simplificado$$, $$mc-cp-3$$, $$Treino de Macro$$,
$$Treino sem nota: seis perguntas rápidas para firmar a base antes do desafio. Nada aqui vale nota; se errar, é só rever o ponto.
[[continuar]]
[[campos: t1]]
Pergunta 1 de 6.
[[continuar]]
[[campos: t2]]
Pergunta 2 de 6.
[[continuar]]
[[campos: t3]]
Pergunta 3 de 6.
[[continuar]]
[[campos: t4]]
Pergunta 4 de 6.
[[continuar]]
[[campos: t5]]
Pergunta 5 de 6.
[[continuar]]
[[campos: t6]]
Pergunta 6 de 6.$$,
$$[{"id": "t1", "tipo": "opcao", "rotulo": "Se a Selic sobe, o que acontece com o juro do financiamento de um carro?", "obrigatorio": true, "opcoes": ["Cai", "Sobe", "Não muda"]}, {"id": "t2", "tipo": "opcao", "rotulo": "A inflação está acima do teto da meta. O que o Banco Central tende a fazer?", "obrigatorio": true, "opcoes": ["Subir ou manter os juros altos", "Cortar os juros", "Nada"]}, {"id": "t3", "tipo": "opcao", "rotulo": "O dólar subiu 10% em um mês. Qual o efeito mais provável na inflação?", "obrigatorio": true, "opcoes": ["Cai", "Sobe", "Não tem relação"]}, {"id": "t4", "tipo": "opcao", "rotulo": "Desemprego baixo e consumo crescendo rápido pressionam a inflação para…", "obrigatorio": true, "opcoes": ["Cima", "Baixo", "Não pressionam"]}, {"id": "t5", "tipo": "opcao", "rotulo": "O boletim Focus mostra que o mercado espera inflação maior. Por que o Banco Central se preocupa?", "obrigatorio": true, "opcoes": ["Não se preocupa, é só opinião", "Expectativas influenciam preços e salários hoje", "Porque o Focus define a Selic"]}, {"id": "t6", "tipo": "opcao", "rotulo": "Se os juros do mercado sobem, o preço de um título prefixado hoje…", "obrigatorio": true, "opcoes": ["Cai", "Sobe", "Fica igual"]}]$$::jsonb,
NULL,
$${"tipo": "treino sem nota", "gabarito": [{"campo": "t1", "tema": "selic", "respostaCerta": "Sobe", "explicacao": "A Selic é a base dos outros juros. Quando ela sobe, os bancos também cobram mais para emprestar.", "seErrar": {"pergunta": "O Banco Central cortou a Selic. O que tende a acontecer com os juros do cartão parcelado e dos empréstimos?", "opcoes": ["Sobem", "Caem", "Não mudam"], "respostaCerta": "Caem"}}, {"campo": "t2", "tema": "selic", "respostaCerta": "Subir ou manter os juros altos", "explicacao": "Juros mais altos encarecem o crédito, esfriam o consumo e ajudam a segurar os preços.", "seErrar": {"pergunta": "A inflação está bem abaixo da meta e a economia está fraca. O que o Banco Central tende a fazer?", "opcoes": ["Subir os juros", "Cortar os juros", "Nada"], "respostaCerta": "Cortar os juros"}}, {"campo": "t3", "tema": "cambio", "respostaCerta": "Sobe", "explicacao": "Importados, combustíveis e insumos ficam mais caros em reais, e parte disso chega aos preços.", "seErrar": {"pergunta": "Por que a gasolina tende a subir quando o dólar sobe?", "opcoes": ["Porque o petróleo é cotado em dólar", "Porque o governo decide assim", "Não tem relação"], "respostaCerta": "Porque o petróleo é cotado em dólar"}}, {"campo": "t4", "tema": "atividade", "respostaCerta": "Cima", "explicacao": "Com mais gente empregada e consumindo, a demanda cresce mais rápido que a oferta, e os preços tendem a subir.", "seErrar": {"pergunta": "Uma economia em recessão, com muita gente desempregada, tende a ter inflação…", "opcoes": ["Mais alta", "Mais baixa", "Igual"], "respostaCerta": "Mais baixa"}}, {"campo": "t5", "tema": "expectativas", "respostaCerta": "Expectativas influenciam preços e salários hoje", "explicacao": "Se todos esperam inflação alta, empresas reajustam preços e trabalhadores pedem aumentos antes, e a inflação vem de fato.", "seErrar": {"pergunta": "Se todo mundo espera que os preços subam muito no ano que vem, o que as empresas tendem a fazer hoje?", "opcoes": ["Reajustar preços antes", "Baixar preços", "Nada"], "respostaCerta": "Reajustar preços antes"}}, {"campo": "t6", "tema": "juros", "respostaCerta": "Cai", "explicacao": "Títulos novos passam a pagar mais, então o antigo vale menos se vendido antes do vencimento. Quem leva até o fim recebe o combinado.", "seErrar": {"pergunta": "Juros subindo: qual tipo de título tende a se beneficiar mais rápido?", "opcoes": ["Pós-fixado, atrelado ao CDI", "Prefixado", "Nenhum"], "respostaCerta": "Pós-fixado, atrelado ao CDI"}}], "comportamentoDoProtótipo": "Resposta com explicação imediata. Quem erra revê o ponto depois, com a pergunta alternativa (seErrar). Ao fim: \"Você acertou tudo\" (todas de primeira) ou \"Treino concluído\". Não vale nota."}$$::jsonb),
($$mc-task-briefing$$, $$mc-simplificado$$, $$mc-cp-4$$, $$Briefing$$,
$$Marina: “Bom dia. O Copom decide na quarta e o comitê quer a nossa leitura. Você vai fazer a análise em cinco capítulos curtos. Comece pelo relatório: quais são os três dados que mais importam para essa decisão?”
[[continuar]]
O relatório da semana está na tabela abaixo.
Marina: “Cuidado com o óbvio. O mercado está dividido. Quero que você me diga o que o Copom vai fazer e por quê.”
[[continuar]]
[[campos: dado_1, dado_2, dado_3, motivo_1, motivo_2, motivo_3]]
Tarefa 1: escolha os três dados mais importantes, cada um diferente dos outros. Tarefa 2: diga por que cada um importa.$$,
$$[{"id": "dado_1", "tipo": "opcao", "rotulo": "Dado mais importante", "obrigatorio": true, "opcoes": ["Selic atual", "Meta de inflação", "IPCA em 12 meses", "Inflação de serviços", "Expectativa de inflação (Focus)", "Desemprego", "PIB do último trimestre", "Dólar", "Expectativa para o Copom"]}, {"id": "dado_2", "tipo": "opcao", "rotulo": "Segundo dado mais importante (diferente dos outros)", "obrigatorio": true, "opcoes": ["Selic atual", "Meta de inflação", "IPCA em 12 meses", "Inflação de serviços", "Expectativa de inflação (Focus)", "Desemprego", "PIB do último trimestre", "Dólar", "Expectativa para o Copom"]}, {"id": "dado_3", "tipo": "opcao", "rotulo": "Terceiro dado mais importante (diferente dos outros)", "obrigatorio": true, "opcoes": ["Selic atual", "Meta de inflação", "IPCA em 12 meses", "Inflação de serviços", "Expectativa de inflação (Focus)", "Desemprego", "PIB do último trimestre", "Dólar", "Expectativa para o Copom"]}, {"id": "motivo_1", "tipo": "opcao", "rotulo": "Por que o primeiro dado importa?", "obrigatorio": true, "opcoes": ["Mostra pressão nos preços", "Mostra a força da economia", "Mostra o que o mercado espera", "Mostra o custo do dinheiro"]}, {"id": "motivo_2", "tipo": "opcao", "rotulo": "Por que o segundo dado importa?", "obrigatorio": true, "opcoes": ["Mostra pressão nos preços", "Mostra a força da economia", "Mostra o que o mercado espera", "Mostra o custo do dinheiro"]}, {"id": "motivo_3", "tipo": "opcao", "rotulo": "Por que o terceiro dado importa?", "obrigatorio": true, "opcoes": ["Mostra pressão nos preços", "Mostra a força da economia", "Mostra o que o mercado espera", "Mostra o custo do dinheiro"]}]$$::jsonb,
$${"titulo": "Relatório Macro Semanal — Arquipélago Investimentos · Reunião do Copom: quarta-feira", "colunas": ["Valor", "Comentário"], "linhas": [{"rotulo": "Selic atual", "celulas": [{"texto": "13,75%", "valor": null}, {"texto": "Ao ano. Mantida nas duas últimas reuniões.", "valor": null}]}, {"rotulo": "Meta de inflação", "celulas": [{"texto": "3,0%", "valor": null}, {"texto": "Teto de 4,5%. Definida pelo governo.", "valor": null}]}, {"rotulo": "IPCA em 12 meses", "celulas": [{"texto": "5,1%", "valor": null}, {"texto": "Acima do teto pelo terceiro mês seguido.", "valor": null}]}, {"rotulo": "Inflação de serviços", "celulas": [{"texto": "6,0%", "valor": null}, {"texto": "Em 12 meses. Subindo; serviços dependem muito de salários.", "valor": null}]}, {"rotulo": "Expectativa de inflação (Focus)", "celulas": [{"texto": "4,6%", "valor": null}, {"texto": "Para 12 meses. Subiu nas últimas quatro semanas.", "valor": null}]}, {"rotulo": "Desemprego", "celulas": [{"texto": "6,2%", "valor": null}, {"texto": "Perto da mínima da série.", "valor": null}]}, {"rotulo": "PIB do último trimestre", "celulas": [{"texto": "+0,9%", "valor": null}, {"texto": "Acima do esperado.", "valor": null}]}, {"rotulo": "Dólar", "celulas": [{"texto": "R$ 5,40", "valor": null}, {"texto": "Estável no mês.", "valor": null}]}, {"rotulo": "Expectativa para o Copom", "celulas": [{"texto": "Dividida", "valor": null}, {"texto": "Metade espera manutenção; metade, alta de 0,25 p.p.", "valor": null}]}]}$$::jsonb,
$${"rubrica": {"criterio": "Leitura de dados", "capitulo": 1, "escala": "1 a 4", "rubricaCompleta": "Ver task mc-task-comite (rubrica geral do case)."}, "dadosChave": {"IPCA em 12 meses": "Mostra pressão nos preços", "Inflação de serviços": "Mostra pressão nos preços", "Expectativa de inflação (Focus)": "Mostra o que o mercado espera", "Desemprego": "Mostra a força da economia"}, "pontuacao": "Considere só os dados escolhidos que estão entre os dados-chave (IPCA, inflação de serviços, Focus, desemprego). Nota 4: três dados-chave, os três com o motivo certo. Nota 3: pelo menos dois dados-chave, com pelo menos dois motivos certos. Nota 2: pelo menos um dado-chave. Nota 1: nenhum (ou sem entrega). Calculada por código.", "distracao": "Dólar (estável no mês) e demais dados sem pressão direta sobre a decisão; o dólar escolhido entre os três motiva a reação da Marina.", "reacoesDaMarina": {"ipca e focus escolhidos": "Boa escolha com o Focus. Muita gente esquece das expectativas.", "dólar escolhido": "O dólar está estável no mês. Por que ele estaria entre os três? Guarde essa resposta: o comitê pode perguntar.", "outros casos": "Ok. Guarde bem seus motivos: o comitê vai perguntar."}, "dicaEva": "Pense no que o Banco Central mais teme. Quais números mostram isso?"}$$::jsonb),
($$mc-task-diagnostico$$, $$mc-simplificado$$, $$mc-cp-5$$, $$Diagnóstico$$,
