$${"rubricaGeral": {"criterios": [{"capitulo": 1, "nome": "Leitura de dados", "escala": "1 a 4", "correcao": "por código, pelos dados e motivos do capítulo 1"}, {"capitulo": 2, "nome": "Causa e efeito", "escala": "1 a 4", "correcao": "avaliadora (IA, às cegas)"}, {"capitulo": 3, "nome": "Decisão e calibração", "escala": "1 a 4", "correcao": "por código, pela decisão, confiança, argumento e carteira"}, {"capitulo": 4, "nome": "Adaptação", "escala": "1 a 4", "correcao": "avaliadora (IA, às cegas)"}, {"capitulo": 5, "nome": "Comunicação", "escala": "1 a 4", "correcao": "avaliadora (IA, às cegas)"}], "total": "5 critérios de 1 a 4 (máximo de 20 pontos)", "medalha": "12 pontos ou mais", "distincao": "17 pontos ou mais", "avaliacao": "Avaliação às cegas: não se considera nome, gênero nem faculdade. Avalia-se o raciocínio, não o palpite. A leitura esperada aponta para alta de juros; \"manter\", bem justificado, também é aceitável."}, "criterioComunicacao": {"1": "Não responde às perguntas.", "2": "Confusa.", "3": "Clara.", "4": "Clara, objetiva e reconhece os próprios riscos."}, "regraDoProtótipo": "Sem IA, aproximação da comunicação: 4 se a apresentação e as três respostas têm mais de 80 caracteres cada; 3 se mais de 40; 2 se mais de 15; senão 1. Exigência de tamanho mínimo: apresentação com 40 caracteres e cada resposta com 15.", "cenarioDoComite": "Inflação de 5,1% acima do teto de 4,5%, inflação de serviços subindo, expectativas subindo para 4,9%, economia aquecida, dólar disparou para R$ 5,85, Selic em 13,75%.", "perguntasDaBanca": [{"quem": "Ricardo", "papel": "gestor, vem de Asset e mercados", "estilo": "pragmático, quer a decisão em uma frase, pensa no que fazer com a carteira amanhã", "pergunta": "Em uma frase: o que eu faço com a carteira amanhã?", "criterio": "Comunicação (capítulo 5)"}, {"quem": "Paula", "papel": "de Risco e Operações", "estilo": "cética, procura o ponto fraco da tese e o que pode dar errado", "pergunta": "Qual dado, se saísse amanhã, derrubaria a sua tese?", "criterio": "Comunicação (capítulo 5)"}, {"quem": "Helena", "papel": "sócia, veio de IB e Private Equity", "estilo": "pensa no longo prazo, no cliente e nas consequências de errar", "pergunta": "E se você estiver errada, quanto isso custa para os nossos clientes?", "criterio": "Comunicação (capítulo 5)"}], "observacaoProtótipo": "No protótipo, cada pergunta é gerada por IA a partir da pergunta-base, adaptada ao que a participante disse; aqui as perguntas-base são fixas.", "desfechoRevelado": {"quando": "Quarta-feira, 18h30 · decisão do Copom", "titulo": "Selic sobe 0,50 p.p., para 14,25%", "comunicado": "No comunicado, o Banco Central cita o dólar e a alta das expectativas.", "consequencias": ["Títulos pós-fixados, atrelados ao CDI, ganham com juros mais altos.", "Títulos prefixados perdem valor no curto prazo.", "O mercado já espera nova alta na próxima reunião."]}, "feedbackFinal": {"formato": "Pontuação por critério, mensagem da Marina (2 ou 3 frases, direta, exigente e justa), ponto mais forte, o que desenvolver (com sugestão prática) e o que um comitê real cortaria.", "mensagemPadraoSemIA": {"forte": "Você entregou todos os capítulos dentro do raciocínio esperado.", "desenvolver": "Treine responder ao comitê em uma frase, começando pela conclusão.", "corte": "Uma recomendação de carteira sem prazo definido.", "marina": "Você chegou até o comitê com uma tese. Agora é lapidar a forma de defender."}}}$$::jsonb)
